+                    + "with CONFIG_SECCOMP and CONFIG_SECCOMP_FILTER compiled in"
+            );
+        }
+    }
+
+    @Override
+    public SockFProg newSockFProg(SockFilter[] filters) {
+        var prog = new JnaSockFProg(filters);
+        prog.write();
+        return prog;
+    }
